part 'package:PiliPlus/common/widgets/context_menu/reply_menu_helper.dart';

class ReplyItemGrpc extends StatelessWidget {
  const ReplyItemGrpc({
    super.key,
    required this.replyItem,
    required this.replyLevel,
    this.replyReply,
    this.needDivider = true,
    this.onReply,
    this.onDelete,
    this.upMid,
    this.showDialogue,
    this.getTag,
    this.onViewImage,
    this.onCheckReply,
    this.onToggleTop,
    this.jumpToDialogue,
    this.youtubeStyle = false,
  });
  final ReplyInfo replyItem;
  final int replyLevel;
  final Function(ReplyInfo replyItem, int? rpid)? replyReply;
  final bool needDivider;
  final ValueChanged<ReplyInfo>? onReply;
  final Function(ReplyInfo replyItem, int? subIndex)? onDelete;
  final Int64? upMid;
  final VoidCallback? showDialogue;
  final Function? getTag;
  final VoidCallback? onViewImage;
  final ValueChanged<ReplyInfo>? onCheckReply;
  final ValueChanged<ReplyInfo>? onToggleTop;
  final VoidCallback? jumpToDialogue;
  final bool youtubeStyle;

  static final _voteRegExp = RegExp(r"^\{vote:\d+?\}$");
  static final _timeRegExp = RegExp(r'^(?:\d+[:：])?\d+[:：]\d+$');
  static bool enableWordRe = Pref.enableWordRe;
  static int? replyLengthLimit = Pref.replyLengthLimit;

  static String _locationSuffix(ReplyControl control) {
    if (!control.hasLocation()) return '';
    final label = replyLocationLabel(control.location);
    return label.isEmpty ? '' : ' · $label';
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = ColorScheme.of(context);

    void showMore() => showCouiBottomSheet(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      constraints: BoxConstraints(
        maxWidth: min(640, context.mediaQueryShortestSide),
      ),
      builder: (context) {
        return morePanel(
          context: context,
          item: replyItem,
          onDelete: () => onDelete?.call(replyItem, null),
          isSubReply: false,
        );
      },
    );

    final useYoutube = youtubeStyle;
    final content = _buildContent(
      context,
      colorScheme,
      youtubeHeader: useYoutube
          ? _buildYoutubeHeader(context, colorScheme)
          : null,
      useYoutube: useYoutube,
    );
    Widget child = Padding(
      padding: EdgeInsets.fromLTRB(
        useYoutube ? VideoDetailChrome.horizontalInset : 12,
        10,
        useYoutube ? VideoDetailChrome.horizontalInset : 8,
        3,
      ),
      child: useYoutube && replyLevel == 1 && replyItem.count > Int64.ZERO
          ? Stack(
              children: [
                Positioned.fill(
                  child: IgnorePointer(
                    child: CustomPaint(
                      painter: YoutubeReplyThreadPainter(
                        CouiThemeData.of(context).dividerColor,
                      ),
                    ),
                  ),
                ),
                content,
              ],
            )
          : content,
    );
    if (needDivider && !useYoutube) {
      child = Column(
        mainAxisSize: .min,
        children: [
          child,
          Divider(
            indent: 55,
            endIndent: 15,
            height: 0.3,
            color: colorScheme.outline.withValues(alpha: 0.08),
          ),
        ],
      );
    }
    return Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: () => replyReply?.call(replyItem, null),
        onLongPress: showMore,
        onSecondaryTap: PlatformUtils.isMobile ? null : showMore,
        child: child,
      ),
    );
  }

  Widget _buildYoutubeHeader(
    BuildContext context,
    ColorScheme scheme,
  ) {
    final member = replyItem.member;
    void openMember() {
      feedBack();
      Get.toNamed('/member?mid=${replyItem.mid}');
    }

    return Row(
      children: [
        GestureDetector(
          onTap: openMember,
          child: PendantAvatar(
            member.face,
            size: 34,
            badgeSize: 14,
            vipStatus: member.vipStatus.toInt(),
            officialType: member.officialVerifyType.toInt(),
            pendantImage: member.hasGarbPendantImage()
                ? member.garbPendantImage
                : null,
          ),
        ),
        const SizedBox(width: 11),
        Expanded(
          child: GestureDetector(
            onTap: openMember,
            child: Row(
              children: [
                Flexible(
                  child: Text(
                    remarkedName(member.mid.toInt(), member.name),
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      fontSize: 13.5,
                      fontWeight: FontWeight.w600,
                      color: member.vipStatus > 0 && member.vipType == 2
                          ? scheme.vipColor
                          : scheme.onSurface,
                    ),
                  ),
                ),
                const SizedBox(width: 5),
                BiliUtils.levelPicture(
                  member.level.toInt(),
                  isSeniorMember: member.isSeniorMember == 1,
                  height: 11,
                ),
                if (replyItem.mid == upMid) ...[
                  const SizedBox(width: 4),
                  const PBadge(text: 'UP', size: .small, isStack: false, fontSize: 9),
                ] else if (GlobalData().showMedal && member.hasFansMedalLevel()) ...[
                  const SizedBox(width: 4),
                  Flexible(
                    child: MedalWidget(
                      medalName: member.fansMedalName,
                      level: member.fansMedalLevel.toInt(),
                      backgroundColor: DmUtils.decimalToColor(member.fansMedalColor.toInt()),
                      nameColor: DmUtils.decimalToColor(member.fansMedalColorName.toInt()),
                      padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 1.5),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ),
        SizedBox(
          width: 32,
          height: 32,
          child: Builder(
            builder: (anchorContext) => IconButton(
              tooltip: '更多评论操作',
              onPressed: () => _showYoutubeMenu(
                anchorContext,
                colorScheme: scheme,
                item: replyItem,
                onDelete: () => onDelete?.call(replyItem, null),
                isSubReply: false,
              ),
              padding: EdgeInsets.zero,
              icon: Icon(
                Icons.more_vert,
                color: scheme.onSurfaceVariant,
                size: 18,
              ),
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildHeader(BuildContext context, ColorScheme colorScheme) {
    final member = replyItem.member;
    Widget header = GestureDetector(
      onTap: () {
        feedBack();
        Get.toNamed('/member?mid=${replyItem.mid}');
      },
      child: TranslucentRow(
        spacing: 12,
        extraWidth: 46,
        children: [
          PendantAvatar(
            member.face,
            size: 34,
            badgeSize: 14,
            vipStatus: member.vipStatus.toInt(),
            officialType: member.officialVerifyType.toInt(),
            pendantImage: member.hasGarbPendantImage()
                ? member.garbPendantImage
                : null,
          ),
          Flexible(
            child: Column(
              mainAxisSize: .min,
              crossAxisAlignment: .start,
              children: [
                Row(
                  spacing: 6,
                  mainAxisSize: .min,
                  children: [
                    Flexible(
                      child: Text(
                        remarkedName(member.mid.toInt(), member.name),
                        maxLines: 1,
                        overflow: .ellipsis,
                        style: TextStyle(
                          color: (member.vipStatus > 0 && member.vipType == 2)
                              ? colorScheme.vipColor
                              : colorScheme.outline,
                          fontSize: 13,
                        ),
                      ),
                    ),
                    BiliUtils.levelPicture(
                      member.level.toInt(),
                      isSeniorMember: member.isSeniorMember == 1,
                      height: 11,
                    ),
                    if (replyItem.mid == upMid)
                      const PBadge(
                        text: 'UP',
                        size: .small,
                        isStack: false,
                        fontSize: 9,
                      )
                    else if (GlobalData().showMedal &&
                        member.hasFansMedalLevel())
                      MedalWidget(
                        medalName: member.fansMedalName,
                        level: member.fansMedalLevel.toInt(),
                        backgroundColor: DmUtils.decimalToColor(
                          member.fansMedalColor.toInt(),
                        ),
                        nameColor: DmUtils.decimalToColor(
                          member.fansMedalColorName.toInt(),
                        ),
                        padding: const .symmetric(horizontal: 6, vertical: 1.5),
                      ),
                  ],
                ),
                Text.rich(
                  maxLines: 1,
                  overflow: .ellipsis,
                  style: TextStyle(fontSize: 11, color: colorScheme.outline),
                  TextSpan(
                    text: replyLevel == 0
                        ? DateFormatUtils.format(
                            replyItem.ctime.toInt(),
                            format: DateFormatUtils.longFormatDs,
                          )
                        : DateFormatUtils.dateFormat(replyItem.ctime.toInt()),
                    children: _locationSuffix(replyItem.replyControl).isEmpty
                        ? null
                        : [
                            TextSpan(
                              text: _locationSuffix(replyItem.replyControl),
                            ),
                          ],
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
    if (PendantAvatar.showDecorate) {
      final garb = replyItem.memberV2.garb;
      if (garb.hasCardImage()) {
        const double height = 38.0;
        return Stack(
          clipBehavior: .none,
          children: [
            Positioned(
              top: 0,
              right: 0,
              height: height,
              child: CachedNetworkImage(
                height: height,
                memCacheHeight: height.cacheSize(context),
                imageUrl: ImageUtils.safeThumbnailUrl(garb.cardImage),
                placeholder: (_, _) => const SizedBox.shrink(),
              ),
            ),
            if (garb.hasCardNumber())
              Positioned(
                top: 0,
                right: 0,
                height: height,
                child: Center(
                  child: Text(
                    '${garb.fanNumPrefix}\n${garb.cardNumber}',
                    style: TextStyle(
                      fontSize: 8,
                      fontFamily: Assets.digitalNum,
                      color: ColourUtils.parseColor(garb.cardFanColor),
                    ),
                  ),
                ),
              ),
            Padding(
              padding: const .only(right: 80),
              child: header,
            ),
          ],
        );
      }
    }
    return header;
  }

  Widget _buildVoteOption(
    ColorScheme colorScheme,
    ReplyControl_VoteOption voteOption,
  ) {
    return Text.rich(
      TextSpan(
        children: [
          switch (voteOption.labelKind) {
            .RED => TextSpan(
              text: '红方  ',
              style: TextStyle(color: colorScheme.vipColor),
            ),
            .BLUE => TextSpan(
              text: '蓝方  ',
              style: TextStyle(color: colorScheme.blue),
            ),
            _ => TextSpan(
              text: '投票  ',
              style: TextStyle(color: colorScheme.outline),
            ),
          },
          TextSpan(text: voteOption.desc),
        ],
      ),
      style: TextStyle(
        height: 1.75,
        fontSize: 12,
        color: colorScheme.onSurfaceVariant,
      ),
    );
  }

  Widget _buildContent(
    BuildContext context,
    ColorScheme colorScheme, {
    Widget? youtubeHeader,
    bool useYoutube = false,
  }) {
    final replyControl = replyItem.replyControl;
    final padding = EdgeInsets.only(left: replyLevel == 0 ? 6 : 45, right: 6);
    return Column(
      mainAxisSize: .min,
      crossAxisAlignment: .start,
      children: [
        youtubeHeader ?? _buildHeader(context, colorScheme),
        SizedBox(height: useYoutube ? 4 : 10),
        if (replyControl.hasVoteOption())
          Padding(
            padding: padding,
            child: _buildVoteOption(colorScheme, replyControl.voteOption),
          ),
        Padding(
          padding: padding,
          child: TextMore.rich(
            primary: colorScheme.primary,
            style: useYoutube
                ? const TextStyle(height: 1.48, fontSize: 14.5)
                : const TextStyle(height: 1.75, fontSize: 14),
            maxLines: replyLevel == 1 ? replyLengthLimit : null,
            TextSpan(
              children: [
                if (replyControl.isUpTop) ...[
                  const WidgetSpan(
                    alignment: .middle,
                    child: PBadge(
                      text: 'TOP',
                      size: .small,
                      isStack: false,
                      type: .line_primary,
                      fontSize: 9,
                      textScaleFactor: 1,
                    ),
                  ),
                  const TextSpan(text: ' '),
                ],
                _buildMessage(
                  context,
                  colorScheme,
                  replyControl.showTranslation
                      ? replyItem.translatedContent
                      : replyItem.content,
                  replyControl,
                ),
              ],
            ),
          ),
        ),
        if (replyItem.content.pictures.isNotEmpty) ...[
          Padding(
            padding: padding,
            child: ImageGridView(
              picArr: replyItem.content.pictures
                  .map(
                    (item) => ImageModel(
                      width: item.imgWidth,
                      height: item.imgHeight,
                      url: item.imgSrc,
                    ),
                  )
                  .toList(),
              onViewImage: onViewImage,
            ),
          ),
          const SizedBox(height: 4),
        ],
        if (replyLevel != 0) ...[
          const SizedBox(height: 4),
          useYoutube
              ? _youtubeActions(context, colorScheme, replyControl)
              : buttonAction(context, colorScheme, replyControl),
        ],
        if (useYoutube)
          _youtubeBottomRow(colorScheme)
        else if (replyLevel == 1 && replyItem.count > Int64.ZERO)
          Padding(
            padding: const EdgeInsets.only(top: 4, bottom: 6),
            child: replyItemRow(context, colorScheme, replyItem.replies),
          ),
      ],
    );
  }

  Widget _youtubeActions(
    BuildContext context,
    ColorScheme scheme,
    ReplyControl control,
  ) {
    const buttonStyle = ButtonStyle(
      visualDensity: .compact,
      tapTargetSize: .shrinkWrap,
      padding: WidgetStatePropertyAll(.zero),
    );
    final textStyle = TextStyle(fontSize: 12, color: scheme.outline);
    return Padding(
      padding: const EdgeInsets.only(left: 45),
      child: Row(
        children: [
          ZanButtonGrpc(replyItem: replyItem, youtubeStyle: true),
          SizedBox(
            width: 40,
            height: 32,
            child: IconButton(
              tooltip: '回复',
              padding: EdgeInsets.zero,
              onPressed: () {
                feedBack();
                onReply?.call(replyItem);
              },
              icon: Icon(Icons.chat_bubble_outline, size: 17, color: scheme.outline),
            ),
          ),
          if (control.translationSwitch ==
              .TRANSLATION_SWITCH_SHOW_TRANSLATION)
            _buildTranslateBtn(context, scheme, control, textStyle, buttonStyle)
          else if (control.cardLabels.isNotEmpty)
            Flexible(
              child: Text(
                control.cardLabels.map((e) => e.textContent).join('  '),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: textStyle.copyWith(color: scheme.secondary),
              ),
            ),
        ],
      ),
    );
  }

  Widget _youtubeBottomRow(ColorScheme scheme) {
    final hasReplies = replyLevel == 1 && replyItem.count > Int64.ZERO;
    final timeLocation =
        '${DateFormatUtils.dateFormat(replyItem.ctime.toInt())}'
        '${_locationSuffix(replyItem.replyControl)}';
    return Padding(
      padding: const EdgeInsets.only(left: 45, right: 6, top: 2, bottom: 4),
      child: Row(
        children: [
          if (hasReplies) _youtubeReplyLink(scheme),
          const Spacer(),
          Text(
            timeLocation,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: TextStyle(fontSize: 11.5, color: scheme.outline),
          ),
        ],
      ),
    );
  }

  Widget _youtubeReplyLink(ColorScheme scheme) {
    final accent = VideoDetailChrome.accent(scheme);
    return Material(
      type: MaterialType.transparency,
      child: InkWell(
        onTap: () => replyReply?.call(replyItem, null),
        borderRadius: const BorderRadius.all(Radius.circular(14)),
        child: DecoratedBox(
          decoration: BoxDecoration(
            color: VideoDetailChrome.pill(scheme),
            borderRadius: const BorderRadius.all(Radius.circular(14)),
          ),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  '共 ${replyItem.count} 条回复',
                  style: TextStyle(
                    color: accent,
                    fontWeight: FontWeight.w600,
                    fontSize: 12.5,
                  ),
                ),
                const SizedBox(width: 2),
                Icon(Icons.chevron_right, size: 15, color: accent),
              ],
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildTranslateBtn(
    BuildContext context,
    ColorScheme colorScheme,
    ReplyControl replyControl,
    TextStyle textStyle,
    ButtonStyle buttonStyle,
  ) {
    late bool isProcessing = false;
    final color = replyControl.showTranslation
        ? colorScheme.primary
        : colorScheme.outline.withValues(alpha: 0.8);
    return SizedBox(
      height: 32,
      child: TextButton(
        style: buttonStyle,
        onPressed: () async {
          if (replyControl.showTranslation) {
            replyControl.showTranslation = false;
            (context as Element).markNeedsBuild();
          } else {
            if (isProcessing) {
              return;
            }
            if (replyItem.hasTranslatedContent()) {
              replyControl.showTranslation = true;
              (context as Element).markNeedsBuild();
              return;
            }
            isProcessing = true;
            final res = await ReplyGrpc.translateReply(
              type: replyItem.type,
              oid: replyItem.oid,
              rpid: replyItem.id,
            );
            if (res case Success(:final response)) {
              final item = response.translatedReplies[replyItem.id];
              if (item != null && item.hasTranslatedContent()) {
                replyControl.showTranslation = true;
                replyItem.translatedContent = item.translatedContent;
                if (context.mounted) {
                  (context as Element).markNeedsBuild();
                }
              } else {
                SmartDialog.showToast('翻译结果为空');
              }
            } else if (res case Error(:final errMsg)) {
              SmartDialog.showToast('翻译失败: $errMsg');
            }
            isProcessing = false;
          }
        },
        child: Row(
          spacing: 3,
          mainAxisSize: .min,
          children: [
            Icon(Icons.translate, size: 16, color: color),
            Text(
              replyControl.showTranslation ? '原文' : '翻译',
              style: textStyle.copyWith(color: color),
            ),
          ],
        ),
      ),
    );
  }

  Widget buttonAction(
    BuildContext context,
    ColorScheme colorScheme,
    ReplyControl replyControl,
  ) {
    final textStyle = TextStyle(
      height: 1,
      fontSize: 12,
      fontWeight: .normal,
      color: colorScheme.outline,
    );
    const buttonStyle = ButtonStyle(
      visualDensity: .compact,
      tapTargetSize: .shrinkWrap,
      padding: WidgetStatePropertyAll(.zero),
    );

    Widget? dialogBtn;
    if (replyLevel == 2 && needDivider && replyItem.id != replyItem.dialog) {
      dialogBtn = SizedBox(
        height: 32,
        child: TextButton(
          onPressed: showDialogue,
          style: buttonStyle,
          child: Text('查看对话', style: textStyle),
        ),
      );
    } else if (replyLevel == 3 && replyItem.parent != replyItem.root) {
      dialogBtn = SizedBox(
        height: 32,
        child: TextButton(
          onPressed: jumpToDialogue,
          style: buttonStyle,
          child: Text('跳转回复', style: textStyle),
        ),
      );
    }
    return Row(
      children: [
        const SizedBox(width: 36),
        SizedBox(
          height: 32,
          child: TextButton(
            style: buttonStyle,
            onPressed: () {
              feedBack();
              onReply?.call(replyItem);
            },
            child: Row(
              spacing: 3,
              mainAxisSize: .min,
              children: [
                Icon(
                  Icons.reply,
                  size: 18,
                  color: colorScheme.outline.withValues(alpha: 0.8),
                ),
                Text('回复', style: textStyle),
              ],
            ),
          ),
        ),
        const SizedBox(width: 2),
        if (replyControl.translationSwitch ==
            .TRANSLATION_SWITCH_SHOW_TRANSLATION) ...[
          _buildTranslateBtn(
            context,
            colorScheme,
            replyControl,
            textStyle,
            buttonStyle,
          ),
          const SizedBox(width: 2),
        ] else if (replyControl.cardLabels.isNotEmpty) ...[
          Text(
            dialogBtn != null
                ? replyControl.cardLabels.first.textContent
                : replyControl.cardLabels.map((e) => e.textContent).join('  '),
            style: textStyle.copyWith(color: colorScheme.secondary),
          ),
          const SizedBox(width: 2),
        ],
        ?dialogBtn,
        const Spacer(),
        ZanButtonGrpc(replyItem: replyItem),
        const SizedBox(width: 5),
      ],
    );
  }

  Widget replyItemRow(
    BuildContext context,
    ColorScheme colorScheme,
    List<ReplyInfo> replies,
  ) {
    final extraRow = replies.length < replyItem.count.toInt();
    final length = replies.length + (extraRow ? 1 : 0);
    return Padding(
      padding: const .only(left: 42, right: 4),
      child: Material(
        animationDuration: .zero,
        color: colorScheme.onInverseSurface,
        borderRadius: const .all(.circular(6)),
        child: Column(
          crossAxisAlignment: .stretch,
          children: [
            if (replies.isNotEmpty)
              ...replies.mapIndexed((index, childReply) {
                final EdgeInsets padding;
                BorderRadius? borderRadius;
                if (length == 1) {
                  padding = const .fromLTRB(8, 5, 8, 5);
                  borderRadius = const .all(.circular(6));
                } else {
                  if (index == 0) {
                    padding = const .fromLTRB(8, 8, 8, 4);
                    borderRadius = const .vertical(top: .circular(6));
                  } else if (index == length - 1) {
                    padding = const .fromLTRB(8, 4, 8, 8);
                    borderRadius = const .vertical(bottom: .circular(6));
                  } else {
                    padding = const .fromLTRB(8, 4, 8, 4);
                  }
                }
                void showMore() => showCouiBottomSheet(
                  context: context,
                  useSafeArea: true,
                  isScrollControlled: true,
                  constraints: BoxConstraints(
                    maxWidth: min(640, context.mediaQueryShortestSide),
                  ),
                  builder: (context) {
                    return morePanel(
                      context: context,
                      item: childReply,
                      onDelete: () => onDelete?.call(replyItem, index),
                      isSubReply: true,
                    );
                  },
                );
                return InkWell(
                  borderRadius: borderRadius,
                  onTap: () =>
                      replyReply?.call(replyItem, childReply.id.toInt()),
                  onLongPress: showMore,
                  onSecondaryTap: PlatformUtils.isMobile ? null : showMore,
                  child: Padding(
                    padding: padding,
                    child: TextEllipsis.rich(
                      style: TextStyle(
                        height: 1.6,
                        fontSize: 14,
                        color: colorScheme.onSurface.withValues(alpha: 0.85),
                      ),
                      overflow: TextOverflow.ellipsis,
                      maxLines: 2,
                      TextSpan(
                        children: [
                          TextSpan(
                            text: remarkedName(
                              childReply.member.mid.toInt(),
                              childReply.member.name,
                            ),
                            style: TextStyle(color: colorScheme.primary),
                            recognizer: NoDeadlineTapGestureRecognizer()
                              ..onTap = () {
                                feedBack();
                                Get.toNamed(
                                  '/member?mid=${childReply.member.mid}',
                                );
                              },
                          ),
                          if (childReply.mid == upMid) ...[
                            const TextSpan(text: ' '),
                            const WidgetSpan(
                              alignment: .middle,
                              child: PBadge(
                                text: 'UP',
                                size: .small,
                                isStack: false,
                                fontSize: 9,
                                textScaleFactor: 1,
                              ),
                            ),
                            const TextSpan(text: ' '),
                          ],
                          if (childReply.root == childReply.parent)
                            const TextSpan(text: ': ')
                          else if (childReply.mid != upMid)
                            const TextSpan(text: ' '),
                          _buildMessage(
                            context,
                            colorScheme,
                            childReply.content,
                            childReply.replyControl,
                          ),
                        ],
                      ),
                    ),
                  ),
                );
              }),

            if (extraRow)
              InkWell(
                onTap: () => replyReply?.call(replyItem, null),
                borderRadius: length == 1
                    ? const .all(.circular(6))
                    : const .vertical(bottom: .circular(6)),
                child: Padding(
                  padding: length == 1
                      ? const .fromLTRB(8, 6, 8, 6)
                      : const .fromLTRB(8, 5, 8, 8),
                  child: Text.rich(
                    TextSpan(
                      style: const TextStyle(fontSize: 12),
                      children: [
                        if (replyItem.replyControl.upReply)
                          TextSpan(
                            text: 'UP主等人 ',
                            style: TextStyle(
                              color: colorScheme.onSurface.withValues(
                                alpha: 0.85,
                              ),
                            ),
                          ),
                        TextSpan(
                          text: '共${replyItem.count}条回复',
                          style: TextStyle(
                            color: colorScheme.primary,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }

  InlineSpan _buildMessage(
    BuildContext context,
    ColorScheme colorScheme,
    Content content,
    ReplyControl replyControl,
  ) {
    final List<InlineSpan> spanChildren = <InlineSpan>[];
    bool hasNote = false;

    final urlKeys = content.urls.keys;
    // 构建正则表达式
    final List<String> specialTokens = [
      ...content.emotes.keys,
      ...content.topics.keys.map((e) => '#$e#'),
      ...content.atNameToMid.keys.map((e) => '@$e'),
      ...urlKeys,
    ];
    String patternStr = [
      ...specialTokens.map(RegExp.escape),
      r'(?:\d+[:：])?\d+[:：]\d+',
      r'\{vote:\d+?\}',
      Constants.urlRegex.pattern,
    ].join('|');
    final RegExp pattern = RegExp(patternStr);

    late List<String> matchedUrls = [];

    void addPlainTextSpan(str) {
      spanChildren.add(TextSpan(text: str));
    }

    void addUrl(String matchStr, Url url, {bool addPlainText = false}) {
      if (url.extra.isWordSearch && !enableWordRe) {
        if (addPlainText) {
          addPlainTextSpan(matchStr);
        }
        return;
      }
      final isCv = url.clickReport.startsWith('{"cvid');
      if (isCv) {
        hasNote = true;
      }
      final children = [
        if (!isCv && url.hasPrefixIcon())
          WidgetSpan(
            child: CachedNetworkImage(
              height: 19,
              memCacheHeight: 19.cacheSize(context),
              color: colorScheme.primary,
              imageUrl: ImageUtils.thumbnailUrl(url.prefixIcon),
              placeholder: (_, _) => const SizedBox.shrink(),
            ),
          ),
        TextSpan(
          text: isCv ? '[笔记] ' : url.title,
          style: TextStyle(color: colorScheme.primary),
          recognizer: NoDeadlineTapGestureRecognizer()
            ..onTap = () {
              if (url.appUrlSchema.isEmpty) {
                if (RegExp(
                  r'^(av|bv)',
                  caseSensitive: false,
                ).hasMatch(matchStr)) {
                  UrlUtils.matchUrlPush(matchStr, '');
                } else {
                  RegExpMatch? match = RegExp(
                    r'^cv(\d+)$|/read/cv(\d+)|note-app/view\?cvid=(\d+)',
                    caseSensitive: false,
                  ).firstMatch(matchStr);
                  String? cvid =
                      match?.group(1) ?? match?.group(2) ?? match?.group(3);
                  if (cvid != null) {
                    Get.toNamed(
                      '/articlePage',
                      parameters: {
                        'id': cvid,
                        'type': 'read',
                      },
                    );
                    return;
                  }
                  PageUtils.handleWebview(matchStr);
                }
              } else {
                if (url.extra.isWordSearch) {
                  Get.toNamed(
                    '/searchResult',
                    parameters: {'keyword': url.title},
                  );
                } else {
                  PageUtils.handleWebview(matchStr);
                }
              }
            },
        ),
      ];
      if (isCv) {
        spanChildren.insertAll(0, children);
      } else {
        spanChildren.addAll(children);
      }
    }

    // 分割文本并处理每个部分
    content.message.splitMapJoin(
      pattern,
      onMatch: (Match match) {
        String matchStr = match[0]!;
        late final name = matchStr.substring(1);
        late final topic = matchStr.substring1;
        if (content.emotes.containsKey(matchStr)) {
          // 处理表情
          final emote = content.emotes[matchStr]!;
          final size = emote.size.toInt() * 20.0;
          final url = emote.hasWebpUrl()
              ? emote.webpUrl
              : emote.hasGifUrl()
              ? emote.gifUrl
              : emote.url;
          spanChildren.add(
            WidgetSpan(
              child: emoteTooltipBuilder(
                url: url,
                emote: matchStr,
                triggerMode: .tap,
                jumpUrl: emote.hasJumpUrl() ? emote.jumpUrl : null,
                colorScheme: colorScheme,
                child: NetworkImgLayer(
                  src: url,
                  type: .emote,
                  width: size,
                  height: size,
                ),
              ),
            ),
          );
        } else if (matchStr.startsWith("@") &&
            content.atNameToMid.containsKey(name)) {
          // 处理@用户
          spanChildren.add(
            TextSpan(
              text: matchStr,
              style: TextStyle(color: colorScheme.primary),
              recognizer: NoDeadlineTapGestureRecognizer()
                ..onTap = () =>
                    Get.toNamed('/member?mid=${content.atNameToMid[name]}'),
            ),
          );
        } else if (_voteRegExp.hasMatch(matchStr)) {
          spanChildren.add(
            TextSpan(
              text: '投票: ${content.vote.title}',
              style: TextStyle(color: colorScheme.primary),
              recognizer: NoDeadlineTapGestureRecognizer()
                ..onTap = () =>
                    showVoteDialog(context, content.vote.id.toInt()),
            ),
          );
        } else if (_timeRegExp.hasMatch(matchStr)) {
          matchStr = matchStr.replaceAll('：', ':');
          bool isValid = false;
          final heroTag = getTag?.call() ?? Get.arguments?['heroTag'];
          if (kDebugMode) {
            debugPrint('Validating timestamp: $matchStr with tag: $heroTag');
          }
          if (heroTag != null) {
            try {
              final ctr = Get.find<AudioController>(tag: heroTag);
              isValid =
                  DurationUtils.parseDuration(matchStr) * 1000 <=
                  ctr.duration.value * 1000;
            } catch (_) {
              try {
                final ctr = Get.find<VideoDetailController>(tag: heroTag);
                isValid =
                    DurationUtils.parseDuration(matchStr) * 1000 <=
                    ctr.data.timeLength!;
              } catch (e) {
                if (kDebugMode) debugPrint('failed to validate: $e');
              }
            }
          }
          spanChildren.add(
            TextSpan(
              text: isValid ? ' $matchStr ' : matchStr,
              style: isValid ? TextStyle(color: colorScheme.primary) : null,
              recognizer: isValid
                  ? (NoDeadlineTapGestureRecognizer()
                      ..onTap = () {
                        // 跳转到指定位置
                        try {
                          final heroTag =
                              getTag?.call() ?? Get.arguments?['heroTag'];
                          final duration = Duration(
                            seconds: DurationUtils.parseDuration(matchStr),
                          );
                          SmartDialog.showToast('跳转至：$matchStr');
                          if (kDebugMode) {
                            debugPrint('Seeking to $duration with tag: $heroTag');
                          }
                          try {
                            final ctr = Get.find<AudioController>(tag: heroTag);
                            if (kDebugMode) debugPrint('Seeking AudioController');
                            ctr.seekTo(
                              duration,
                              isSeek: false,
                            );
                          } catch (_) {
                            final ctr = Get.find<VideoDetailController>(tag: heroTag);
                            if (kDebugMode) debugPrint('Seeking VideoDetailController');
                            ctr.plPlayerController.seekTo(
                              duration,
                              isSeek: false,
                            );
                          }
                        } catch (e) {
                          SmartDialog.showToast('跳转失败: $e');
                          if (kDebugMode) debugPrint('Seek error: $e');
                        }
                      })
                  : null,
            ),
          );
        } else {
          final url = content.urls[matchStr];
          if (url != null && !matchedUrls.contains(matchStr)) {
            addUrl(matchStr, url, addPlainText: true);
            // 只显示一次
            matchedUrls.add(matchStr);
          } else if (matchStr.length > 1 && content.topics[topic] != null) {
            spanChildren.add(
              TextSpan(
                text: matchStr,
                style: TextStyle(color: colorScheme.primary),
                recognizer: NoDeadlineTapGestureRecognizer()
                  ..onTap = () {
                    Get.toNamed(
                      '/searchResult',
                      parameters: {'keyword': topic},
                    );
                  },
              ),
            );
          } else if (Constants.urlRegex.hasMatch(matchStr)) {
            spanChildren.add(
              TextSpan(
                text: matchStr,
                style: TextStyle(color: colorScheme.primary),
                recognizer: NoDeadlineTapGestureRecognizer()
                  ..onTap = () => PageUtils.handleWebview(matchStr),
              ),
            );
          } else {
            addPlainTextSpan(matchStr);
          }
        }
        return '';
      },
      onNonMatch: (String nonMatchStr) {
        addPlainTextSpan(nonMatchStr);
        return nonMatchStr;
      },
    );

    if (!hasNote && replyControl.isNote && replyControl.isNoteV2) {
      final Color color;
      NoDeadlineTapGestureRecognizer? recognizer;

      final hasClickUrl = content.richText.note.hasClickUrl();
      if (hasClickUrl || content.richText.opus.hasOpusId()) {
        color = colorScheme.primary;
        recognizer = NoDeadlineTapGestureRecognizer()
          ..onTap = () => hasClickUrl
              ? PiliScheme.routePushFromUrl(content.richText.note.clickUrl)
              : Get.toNamed(
                  '/articlePage',
                  parameters: {
                    'id': content.richText.opus.opusId.toString(),
                    'type': 'opus',
                  },
                );
      } else {
        color = colorScheme.secondary;
      }
      spanChildren.insert(
        0,
        TextSpan(
          text: '[笔记] ',
          style: TextStyle(color: color),
          recognizer: recognizer,
        ),
      );
    }

    return TextSpan(children: spanChildren);
  }

  Future<void> _confirmAndDeleteReply(
    BuildContext context,
    ReplyInfo item,
    Int64 ownerMid,
    VoidCallback onDelete,
  ) async {
    final message = item.content.message;
    final bool? isDelete = await showDialog<bool>(
      context: context,
      builder: (context) {
        final colorScheme = ColorScheme.of(context);
        return AlertDialog(
          title: const Text('删除评论'),
          content: Text.rich(
            TextSpan(
              children: [
                const TextSpan(text: '确定删除这条评论吗？\n\n'),
                if (ownerMid != item.member.mid.toInt()) ...[
                  TextSpan(
                    text: '@${item.member.name}',
                    style: TextStyle(
                      color: colorScheme.primary,
                    ),
                  ),
                  const TextSpan(text: ':\n'),
                ],
                TextSpan(text: message),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Get.back(result: false),
              child: Text(
                '取消',
                style: TextStyle(
                  color: colorScheme.outline,
                ),
              ),
            ),
            TextButton(
              onPressed: () => Get.back(result: true),
              child: const Text('确定'),
            ),
          ],
        );
      },
    );
    if (isDelete == null || !isDelete) {
      return;
    }
    SmartDialog.showLoading(msg: '删除中...');
    final res = await VideoHttp.replyDel(
      type: item.type.toInt(),
      oid: item.oid.toInt(),
      rpid: item.id.toInt(),
    );
    SmartDialog.dismiss();
    if (res.isSuccess) {
      SmartDialog.showToast('删除成功');
      onDelete();
    } else {
      SmartDialog.showToast('删除失败, $res');
    }
  }

  void _reportReply(
    BuildContext context,
    ColorScheme colorScheme,
    ReplyInfo item,
    VoidCallback onDelete,
  ) {
    final oid = item.oid;
    final rpid = item.id;
    autoWrapReportDialog(
      context,
      onRemove: onDelete,
      mid: () => item.mid.toInt(),
      ReportOptions.commentReport,
      withContent: ReportOptions.withContentReply,
      contentRequired: ReportOptions.contentRequiredReply,
      reportUrl:
          'https://www.bilibili.com/h5/comment/report?oid=$oid&pageType=${item.type}&rpid=$rpid&platform=android&build=8430300&${ThemeUtils.themeUrl(colorScheme.isDark)}',
      (reasonType, reasonDesc, banUid) async {
        final res = await ReplyHttp.report(
          rpid: rpid,
          oid: oid,
          reasonType: reasonType,
          reasonDesc: reasonDesc,
          banUid: banUid,
        );
        if (res.isSuccess) {
          onDelete();
        }
        return res;
      },
    );
  }

  void _blockReplyUser(ReplyInfo item) {
    final mid = item.member.mid.toInt();
    final rawName = item.member.name.trim();
    final name = rawName.isEmpty ? 'UID:$mid' : rawName;
    final mids = Map<int, String>.from(Pref.replyBlockedMids);
    mids[mid] = name;
    Pref.replyBlockedMids = mids;
    ReplyGrpc.replyBlockedMids = mids;
    SmartDialog.showToast('已屏蔽 $name');
  }

  void _showYoutubeMenu(
    BuildContext anchorContext, {
    required ColorScheme colorScheme,
    required ReplyInfo item,
    required VoidCallback onDelete,
    required bool isSubReply,
  }) {
    final message = item.content.message;
    final ownerMid = Int64(Accounts.main.mid);
    final items = <CouiMenuEntry<void>>[
      if (kDebugMode && GStorage.reply != null) ...[
        CouiMenuItem<void>(
          icon: Icons.save_outlined,
          label: 'save to local',
          onTap: () {
            GStorage.reply!.put(
              item.id.toString(),
              (item.deepCopy()
                    ..unknownFields.clear()
                    ..replies.clear()
                    ..clearTrackInfo())
                  .writeToBuffer(),
            );
          },
        ),
        CouiMenuItem<void>(
          icon: Icons.delete_sweep_outlined,
          label: 'remove from local',
          onTap: () {
            onDelete();
            GStorage.reply!.delete(item.id.toString());
          },
        ),
        CouiMenuItem<void>(
          icon: Icons.save_as_outlined,
          label: 'save to local (x1000)',
          onTap: () {
            final oid = item.oid.toInt();
            final data = (item.deepCopy()
                  ..unknownFields.clear()
                  ..replies.clear()
                  ..clearTrackInfo())
                .writeToBuffer();
            GStorage.reply!.putAll({
              for (var i = oid; i < oid + 1000; i++) i.toString(): data,
            });
          },
        ),
        const CouiMenuDivider<void>(),
      ],
      if (ownerMid == upMid || ownerMid == item.member.mid)
        CouiMenuItem<void>(
          icon: Icons.delete_outlined,
          label: '删除',
          isDestructive: true,
          onTap: () => _confirmAndDeleteReply(
            anchorContext,
            item,
            ownerMid,
            onDelete,
          ),
        ),
      if (ownerMid == Int64.ZERO)
        CouiMenuItem<void>(
          icon: Icons.error_outline,
          label: '屏蔽',
          isDestructive: true,
          onTap: () {
            Pref.setBlackMid(item.mid.toInt());
            onDelete();
            SmartDialog.showToast('屏蔽成功');
          },
        )
      else
        CouiMenuItem<void>(
          icon: Icons.error_outline,
          label: '举报',
          isDestructive: true,
          onTap: () => _reportReply(anchorContext, colorScheme, item, onDelete),
        ),
      if (item.member.mid != Int64.ZERO)
        CouiMenuItem<void>(
          icon: Icons.person_off_outlined,
          label: '屏蔽用户',
          onTap: () => _blockReplyUser(item),
        ),
      const CouiMenuDivider<void>(),
      if (replyLevel == 1 && !isSubReply && ownerMid == upMid)
        CouiMenuItem<void>(
          icon: Icons.vertical_align_top,
          label: '${replyItem.replyControl.isUpTop ? '取消' : ''}置顶',
          onTap: () => onToggleTop?.call(item),
        ),
      CouiMenuItem<void>(
        icon: Icons.copy_all_outlined,
        label: '复制全部',
        onTap: () => Utils.copyText(message),
      ),
      CouiMenuItem<void>(
        icon: Icons.copy_outlined,
        label: '自由复制',
        onTap: () => showReplyCopyDialog(
          anchorContext,
          message,
          item.content.emotes,
        ),
      ),
      CouiMenuItem<void>(
        icon: Icons.save_alt,
        label: '保存评论',
        onTap: () => SavePanel.toSavePanel(upMid: upMid, item: item),
      ),
      if (kDebugMode || item.mid == ownerMid)
        CouiMenuItem<void>(
          icon: CustomIcons.shield_reply,
          label: '检查评论',
          onTap: () => onCheckReply?.call(item),
        ),
    ];

    showCouiMenu<void>(
      context: anchorContext,
      anchorContext: anchorContext,
      items: items,
    );
  }

