            child: SingleChildScrollView(
              scrollDirection: .horizontal,
              hitTestBehavior: .translucent,
              physics: ReloadScrollPhysics(controller: introController),
              child: Row(
                spacing: 25,
                children: staff
                    .map((e) => _buildStaff(isPortrait, mid, e))
                    .toList(),
              ),
            ),
          )
        else ...[
          Expanded(
            child: Align(
              alignment: .centerLeft,
              child: _buildAvatar(
                () {
                  if (mid != null) {
                    feedBack();
                    if (!isPortrait && introController.horizontalMemberPage) {
                      widget.onShowMemberPage(mid);
                    } else {
                      Get.toNamed(
                        '/member?mid=$mid&from_view_aid=${videoDetailCtr.aid}',
                      );
                    }
                  }
                },
              ),
            ),
          ),
          followButton(context),
        ],
        if (isHorizontal) ...[
          const SizedBox(width: 10),
          Expanded(
            child: actionGrid(
              context,
              isLoading,
              introController,
              videoDetail.stat,
            ),
          ),
        ],
      ],
    );
  }

  Widget _buildStaff(
    bool isPortrait,
    int? ownerMid,
    Staff item,
  ) {
    void onTap() => Get.toNamed(
      '/member?mid=${item.mid}&from_view_aid=${videoDetailCtr.aid}',
    );
    return GestureDetector(
      behavior: .opaque,
      onTap: () {
        if (item.mid == ownerMid &&
            !isPortrait &&
            introController.horizontalMemberPage) {
          widget.onShowMemberPage(ownerMid);
        } else {
          onTap();
        }
      },
      onSecondaryTap:
          PlatformUtils.isDesktop && introController.horizontalMemberPage
          ? onTap
          : null,
      child: Row(
        children: [
          Stack(
            clipBehavior: .none,
            children: [
              NetworkImgLayer(
                type: .avatar,
                src: item.face,
                width: 35,
                height: 35,
                fadeInDuration: Duration.zero,
                fadeOutDuration: Duration.zero,
              ),
              if (item.official?.type case final type? when type != -1)
                Positioned(
                  right: -2,
                  bottom: -2,
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      shape: .circle,
                      color: colorScheme.surface,
                    ),
                    child: item.official?.type == 0
                        ? const Icon(
                            Icons.offline_bolt,
                            color: BiliColors.yellow,
                            size: 14,
                          )
                        : const Icon(
                            Icons.offline_bolt,
                            color: Colors.lightBlueAccent,
                            size: 14,
                          ),
                  ),
                ),

              Positioned(
                top: 0,
                right: -6,
                child: Obx(
                  () {
                    if (introController.staffRelations['status'] == true &&
                        introController.staffRelations['${item.mid}'] == null) {
                      return Material(
                        type: .circle,
                        color: colorScheme.secondaryContainer,
                        child: InkWell(
                          customBorder: const CircleBorder(),
                          onTap: () => RequestUtils.actionRelationMod(
                            context: context,
                            mid: item.mid,
                            isFollow: false,
                            afterMod: (val) =>
                                introController.staffRelations['${item.mid}'] =
                                    true,
                          ),
                          child: Padding(
                            padding: const .all(2),
                            child: Icon(
                              MdiIcons.plus,
                              size: 16,
                              color: colorScheme.onSecondaryContainer,
                            ),
                          ),
                        ),
                      );
                    }
                    return const SizedBox.shrink();
                  },
                ),
              ),
            ],
          ),
          const SizedBox(width: 8),
          Column(
            mainAxisSize: .min,
            crossAxisAlignment: .start,
            children: [
              Text(
                remarkedName(
                  item.mid is int ? item.mid : int.tryParse('${item.mid}'),
                  item.name!,
                ),
                maxLines: 1,
                overflow: .ellipsis,
                style: TextStyle(
                  fontSize: 13,
                  color: (item.vip?.status ?? 0) > 0 && item.vip?.type == 2
                      ? colorScheme.vipColor
                      : null,
                ),
              ),
              Text(
                item.title!,
                style: TextStyle(fontSize: 12, color: colorScheme.outline),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildAvatar(
    VoidCallback onPushMember,
  ) => GestureDetector(
    onTap: onPushMember,
    behavior: .opaque,
    onSecondaryTap:
        PlatformUtils.isDesktop && introController.horizontalMemberPage
        ? () => Get.toNamed(
            '/member?mid=${introController.userStat.value.card?.mid}&from_view_aid=${videoDetailCtr.aid}',
          )
        : null,
    child: Obx(
      () {
        final userStat = introController.userStat.value;
        final isVip = (userStat.card?.vip?.status ?? 0) > 0;
        final ownerMid = int.tryParse(userStat.card?.mid ?? '');
        return Row(
          spacing: 10,
          mainAxisSize: .min,
          children: [
            PendantAvatar(
              userStat.card?.face,
              size: 35,
              badgeSize: 14,
              vipStatus: userStat.card?.vip?.status,
              officialType: userStat.card?.official?.type,
            ),
            Flexible(
              child: Column(
                crossAxisAlignment: .start,
                children: [
                  Text.rich(
                    maxLines: 1,
                    overflow: .ellipsis,
                    TextSpan(
                      children: [
                        TextSpan(
                          text: remarkedName(
                            ownerMid,
                            userStat.card?.name ?? '',
                          ),
                          style: TextStyle(
                            fontSize: 13,
                            color: isVip && userStat.card?.vip?.type == 2
                                ? colorScheme.vipColor
                                : null,
                          ),
                        ),
                        if (!GlobalData().remarkReplaceName &&
                            remarkOf(ownerMid) != null)
                          TextSpan(
                            text: '（${remarkOf(ownerMid)}）',
                            style: TextStyle(
                              fontSize: 12,
                              color: colorScheme.primary,
                            ),
                          ),
                      ],
                    ),
                  ),
                  Text(
                    '${NumUtils.numFormat(userStat.follower)}粉丝    ${'${NumUtils.numFormat(userStat.archiveCount)}视频'}',
                    style: TextStyle(fontSize: 12, color: colorScheme.outline),
                  ),
                ],
              ),
            ),
          ],
        );
      },
    ),
  );

  Widget _buildInfo(VideoStat? stat, int? pubdate) {
    return Row(
      spacing: 10,
      children: [
        StatWidget(
          type: .play,
          value: stat?.view,
          color: colorScheme.outline,
        ),
        StatWidget(
          type: .danmaku,
          value: stat?.danmaku,
          color: colorScheme.outline,
        ),
        Text(
          DateFormatUtils.format(pubdate),
          style: TextStyle(
            fontSize: 12,
            color: colorScheme.outline,
          ),
        ),
        if (MineController.anonymity.value)
          Icon(
            MdiIcons.incognito,
            size: 15,
            color: colorScheme.outline,
            semanticLabel: '无痕',
          ),
        if (introController.isShowOnlineTotal)
          Obx(
            () => Text(
              '${introController.total.value}人在看',
              style: TextStyle(fontSize: 12, color: colorScheme.outline),
            ),
          ),
      ],
    );
  }

  Widget get _aiBtn => Positioned(
    right: 8,
    child: Center(
      child: GestureDetector(
        behavior: .opaque,
        onTap: () async {
          if (introController.aiConclusionResult == null) {
            await introController.aiConclusion();
          }
          if (introController.aiConclusionResult case AiConclusionResult(
            :final summary,
            :final outline,
          )) {
            if (summary?.isNotEmpty == true || outline?.isNotEmpty == true) {
              widget.showAiBottomSheet();
            } else {
              SmartDialog.showToast("当前视频不支持AI视频总结");
            }
          }
        },
        child: Image.asset(
          semanticLabel: 'AI总结',
          Assets.ai,
          height: 18,
          width: 18,
          cacheHeight: 18.cacheSize(context),
        ),
      ),
    ),
  );

  Widget _buildTags(List<VideoTagItem> tags) {
    return Padding(
      padding: const .only(top: 8),
      child: Wrap(
        spacing: 8,
        runSpacing: 8,
        children: tags
            .map(
              (item) => SearchText(
                fontSize: 13,
                text: switch (item.tagType) {
                  'bgm' => item.tagName!.replaceFirst('发现', '♫ BGM：'),
                  'topic' => '#${item.tagName}',
                  _ => item.tagName!,
                },
                onTap: switch (item.tagType) {
                  'bgm' => (_) => Get.toNamed(
                    '/musicDetail',
                    parameters: {'musicId': item.musicId!},
                  ),
                  'topic' => (_) => Get.toNamed(
                    '/dynTopic',
                    parameters: {'id': item.tagId!.toString()},
                  ),
                  _ => (tagName) => Get.toNamed(
                    '/searchResult',
                    parameters: {'keyword': tagName},
                  ),
                },
                onLongPress: Utils.copyText,
              ),
            )
            .toList(),
      ),
    );
  }
}
